import json,hashlib,re,subprocess
base=Path('reports/skill-atlas');data=json.loads((base/'sources.json').read_text());old=json.loads(subprocess.check_output(['git','show','HEAD:reports/skill-atlas/sources.json'],text=True))
assert data['skills']==old['skills'] and len(data['skills'])==122
assert (base/'catalog.js').read_text()=='window.SKILL_ATLAS = '+json.dumps(data,ensure_ascii=False,indent=2)+';\n'
