 if key not in ['reviewCodeChangesReview','supplementary']:assert data[key]==value,key
for key,value in old['reviewCodeChangesReview'].items():assert data['reviewCodeChangesReview'][key]==value,key
for x in old['supplementary']:assert x in data['supplementary']
assert len({x['id'] for x in data['supplementary']})==len(data['supplementary'])
keys={x['key'] for x in data['skills']}|{x['id'] for x in data['supplementary']}
class Atlas(HTMLParser):
 def __init__(self):super().__init__();self.ids=[];self.refs=[];self.scripts=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.append(a['id'])
  if 'data-evidence' in a:self.refs.extend(a['data-evidence'].split(';'))
  if tag=='script' and 'src' in a:self.scripts.append(a['src'])
p=Atlas();p.feed((base/'index.html').read_text());assert len(p.ids)==len(set(p.ids));assert set(p.refs)<=keys
for f in p.scripts:
 path,_,query=f.partition('?');assert (base/path).exists()
 if query:assert query=='v='+hashlib.sha256((base/path).read_bytes()).hexdigest()[:12],f
