import io
from permissions import permitted_documents

def eager_export(session, store):
    if "analyst" not in session["roles"]:
        raise PermissionError("export role required")
    rows = permitted_documents(session, store.load())
    return "".join(row["text"] + "\n" for row in rows)

def stream_export(session, store):
    rows = [row for row in store.load() if row["tenant"] == session["tenant"]]
    with io.StringIO("".join(row["text"] + "\n" for row in rows)) as source:
        chunks = (line for line in source)
        return {"count": len(rows), "chunks": chunks}

